-- CPF reference optional Batch education pack. Owner: DB Tool REFERENCE_FIXTURE.
CREATE TABLE CPF_REF_BAT_JOB_EXECUTION (
    JOB_EXECUTION_KEY VARCHAR2(200) NOT NULL,
    REQUIREMENT_ID VARCHAR2(32) NOT NULL,
    BUSINESS_KEY VARCHAR2(200) NOT NULL,
    DATA_SCOPE VARCHAR2(500) NOT NULL,
    JOB_NAME VARCHAR2(128) NOT NULL,
    JOB_INSTANCE_KEY VARCHAR2(200) NOT NULL,
    IDEMPOTENCY_KEY VARCHAR2(200) NOT NULL,
    STATE VARCHAR2(40) NOT NULL,
    FENCING_TOKEN NUMBER(19) NOT NULL,
    ATTEMPT_COUNT NUMBER(10) NOT NULL,
    PAYLOAD_JSON CLOB NOT NULL,
    RESULT_JSON CLOB NOT NULL,
    CREATED_AT TIMESTAMP(6) NOT NULL,
    UPDATED_AT TIMESTAMP(6) NOT NULL,
    COMPLETED_AT TIMESTAMP(6) NULL,
    CONSTRAINT PK_REF_BAT_JOB_EXEC PRIMARY KEY (JOB_EXECUTION_KEY),
    CONSTRAINT UK_REF_BAT_JOB_IDEM UNIQUE (REQUIREMENT_ID, IDEMPOTENCY_KEY)
);
CREATE INDEX IX_REF_BAT_JOB_STATE ON CPF_REF_BAT_JOB_EXECUTION (STATE, UPDATED_AT);
CREATE INDEX IX_REF_BAT_JOB_BIZ ON CPF_REF_BAT_JOB_EXECUTION (REQUIREMENT_ID, BUSINESS_KEY, CREATED_AT);

CREATE TABLE CPF_REF_BAT_CHECKPOINT (
    JOB_EXECUTION_KEY VARCHAR2(200) NOT NULL,
    STEP_NAME VARCHAR2(128) NOT NULL,
    PARTITION_KEY VARCHAR2(200) NOT NULL,
    CHECKPOINT_VERSION NUMBER(19) NOT NULL,
    STATE VARCHAR2(40) NOT NULL,
    CHECKPOINT_JSON CLOB NOT NULL,
    UPDATED_AT TIMESTAMP(6) NOT NULL,
    CONSTRAINT PK_REF_BAT_CHECKPOINT PRIMARY KEY (JOB_EXECUTION_KEY, STEP_NAME, PARTITION_KEY),
    CONSTRAINT FK_REF_BAT_CP_JOB FOREIGN KEY (JOB_EXECUTION_KEY) REFERENCES CPF_REF_BAT_JOB_EXECUTION (JOB_EXECUTION_KEY)
);
CREATE INDEX IX_REF_BAT_CP_STATE ON CPF_REF_BAT_CHECKPOINT (STATE, UPDATED_AT);

CREATE TABLE CPF_REF_BAT_TARGET_RESULT (
    TARGET_RESULT_ID VARCHAR2(64) NOT NULL,
    JOB_EXECUTION_KEY VARCHAR2(200) NOT NULL,
    TARGET_KEY VARCHAR2(200) NOT NULL,
    STATE VARCHAR2(40) NOT NULL,
    ATTEMPT_COUNT NUMBER(10) NOT NULL,
    RESULT_JSON CLOB NOT NULL,
    ERROR_CODE VARCHAR2(64) NOT NULL,
    ERROR_MESSAGE VARCHAR2(1000) NOT NULL,
    UPDATED_AT TIMESTAMP(6) NOT NULL,
    CONSTRAINT PK_REF_BAT_TARGET PRIMARY KEY (TARGET_RESULT_ID),
    CONSTRAINT FK_REF_BAT_TARGET_JOB FOREIGN KEY (JOB_EXECUTION_KEY) REFERENCES CPF_REF_BAT_JOB_EXECUTION (JOB_EXECUTION_KEY),
    CONSTRAINT UK_REF_BAT_TARGET UNIQUE (JOB_EXECUTION_KEY, TARGET_KEY)
);
CREATE INDEX IX_REF_BAT_TARGET_STATE ON CPF_REF_BAT_TARGET_RESULT (STATE, UPDATED_AT);
